def guide(name,title,component,rows,tools):
 d={'schema_version':1,'id':'yamaha-2025-yz450f-'+name,'title':title,'target':{'manufacturer':'Yamaha','model':'YZ450F','model_year':2025,'region':'US','variant':'standard'},'scope_confirmed':True,'status':'SOURCE_REVIEW_CANDIDATE','publication_status':'PENDING_INDEPENDENT_REVIEW','component':component,'affected_components':[component,'suspension'],'applicability':{'included':'Exact standard US2025 YZ450F original stock suspension.','excluded':['Other years, replacement springs/components or aftermarket damping conversions','Internal fork/shock overhaul'],'year_inheritance':'NONE'},'entry_state':['Assembled bike, serviceable stock suspension, exact original adjusters identified.'],'exit_state':['Recorded adjustment and functional checks complete; no internal service performed.'],'preflight':['Record actual starting settings.','Stop for leaks, damage, binding or an unidentified adjuster.','Keep the linked diagrams visible to identify distinct controls.'],'critical_stop_conditions':['Damaged or binding suspension','Adjuster at stop before target, inability to identify stock control, or unresolved setup measurement'],'required_tools':[{'name':t} for t in tools],'required_parts':[],'source':{'source_url':U,'document_sha256':H,'document_revision':'D02-2819U-10 / LIT-11626-38-16; March2024','pdf_pages':sorted(set(n for r in rows for n in r[3])),'printed_pages':[],'review_status':'PENDING_INDEPENDENT_REVIEW','review_note':'Exact2025 source independently read and relevant diagrams rendered; root independent review requested.'},'steps':[]}
 for n in d['source']['pdf_pages']:d['source']['printed_pages'].append(pdf[n-1].get_text().strip().splitlines()[-1])
 for i,(id,title,ins,pages,record) in enumerate(rows):d['steps'].append({'id':id,'title':title,'instruction':ins,'depends_on':[rows[i-1][0]] if i else [],'source_pdf_pages':pages,'source_links':[U+'#page='+str(n) for n in pages],'diagram_reference_required':True,'verification':['Confirm the described outcome; record actual settings/measurements where requested.'],'record_required':record,'origin':'Original exact-source summary; recording/comparison are workflow adaptations.'})
 (P/(name+'.procedure.json')).write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
guide('fork-baseline-v1','Restore the stock fork damping baseline','fork',[
 ('inspect','Inspect both legs','Support the assembled bike upright. Inspect inner tubes for damage and fork joints for leaks. Apply front brake and compress the fork several times; it must rebound smoothly. Resolve damage/leaks/binding before adjusting.',[111],True),
 ('record','Record both sides','Identify bottom rebound and top compression controls from PDF112. Gently turn each toward full hard, counting and saving the original clicks so they can be restored. Never force a stop. Actual total travel can vary from nominal; do not manufacture missing clicks.',[112],True),
 ('bleed','Release trapped air','Raise front wheel securely. Remove each leg bleed screw shown PDF113 to release internal pressure, then refit each at1.3Nm. Keep dirt out and return both screws before setting damping.',[112,113],False),
 ('rebound','Set rebound','From gently seated full hard, turn each lower rebound adjuster10 clicks outward in diagram direction b. Both legs must match. Source nominal range is0–20 clicks; stop if actual mechanism cannot reach the standard without force.',[112],True),
 ('compression','Set compression','From gently seated full hard, turn each top compression adjuster12 clicks outward in diagram direction b. Both legs must match. Source nominal range is0–20 clicks; never force beyond actual travel.',[112],True),
 ('verify','Verify the baseline','Lower the bike from its stand. Recheck smooth fork action, both secured bleed screws and matched settings. Record rebound10/compression12 clicks out per leg and any unresolved symptoms. This restores damping only; fork height, oil and springs were not changed.',[111,112,113],True)
 ],['Secure front-wheel maintenance stand','Appropriate damping driver and precision torque tool for1.3Nm'])
guide('shock-baseline-v1','Restore the stock shock damping baseline','shock',[
 ('inspect','Inspect the stock shock','Support the assembled bike upright. Check shock for oil/gas leakage and rear suspension/linkage for smooth movement by sitting astride and moving up/down. Resolve leakage, damage or rough action before setup. Raise rear wheel securely for adjustment.',[113],True),
 ('record','Identify and record the controls','Use PDF114–115 to distinguish rebound, outer high-speed compression and inner low-speed compression. Gently count each starting setting back to its full-hard stop, recording clicks or turns. Never force. This2025 shock is not the revised2026 tool-free unit.',[114,115],True),
 ('rebound','Set rebound','From gently seated full hard in direction a, turn rebound12 clicks outward in direction b. Nominal range is0–30 clicks, with production variation acknowledged by Yamaha. Stop if the actual control cannot reach the standard.',[114],True),
 ('high','Set high-speed compression','Set the high-speed compression control to1 full turn outward in direction b from gently seated full hard. Nominal range is0–2 turns. Identify this control in the diagram so the concentric low-speed control is not substituted.',[114,115],True),
 ('low','Set low-speed compression','Set the distinct low-speed compression screw9 clicks outward in direction b from gently seated full hard. Nominal range is0–20 clicks. Do not force a stop or silently translate turns into clicks.',[115],True),
 ('verify','Verify the recorded baseline','Lower the bike and check rear movement is smooth. Record rebound12 clicks, high-speed1 turn and low-speed9 clicks out, plus actual control travel concerns. Spring preload and sag are separate measured settings and were not changed here.',[113,114,115],True)
 ],['Secure rear-wheel maintenance stand','Appropriate separate rebound/low-speed driver and high-speed adjuster tool'])
guide('rider-sag-preload-v1','Measure rider sag and adjust stock spring preload','shock',[
 ('inspect','Confirm stock spring and serviceability','Confirm original stock spring and smooth leak-free rear suspension. Clean dirt/mud from locknut and adjusting ring. Record existing installed spring length before loosening anything. This route adjusts the original spring, not a replacement spring or shock.',[113,384,385],True),
 ('extended','Measure the unloaded reference','Support under the engine with rear wheel fully off the ground. Measure distance a between rear axle center and the exact marked rear-fender point shown PDF384. Record both reference points and the measurement; use them unchanged throughout.',[384],True),
 ('loaded','Measure with the rider','Remove the stand and support the bike upright with a helper. With the rider astride the seat, measure distance b between the same axle center/fender mark. Record rider/equipment for repeatability. Calculate a minus b; Yamaha target is90–100mm. If already within range and current preload is valid, record it without changing the spring.',[384],True),
 ('free-length','Establish the spring reference if adjustment is needed','Raise rear wheel again. Loosen locknut, then back off adjusting ring until a small clearance exists between ring and spring. Measure actual free spring length as PDF113 shows. Do not remove the spring or use a guessed catalog length. Keep the spring seated while making the next adjustment.',[113],True),
 ('adjust','Set preload within limits','Turn the ring in diagram direction b to increase preload or c to decrease it. Allowed shortening from measured free length is1.5–18.0mm; stock reference is8.0mm. One ring turn changes installed length1.5mm. Choose a measured setting within those bounds to approach90–100mm rider sag, then tighten the locknut as Yamaha directs; this section gives no numeric locknut torque.',[113,114,384,385],True),
 ('remeasure','Recheck with the same rider','Remove stand and repeat a/b measurements under the same conditions. Repeat adjustment only with rear wheel raised and within the measured preload bounds, securing the locknut each time. If90–100mm cannot be achieved within those limits, stop this stock-spring route: source calls for an appropriate optional spring and readjustment, not extra preload beyond the limit.',[113,114,384],True),
 ('record','Record the accepted setup','Record free/installed spring length, preload amount, unloaded a, rider-loaded b and resulting sag. Verify locknut secure and rear action smooth. Reevaluate after initial break-in because the spring can settle. Spring selection, damping changes and internal shock servicing remain separate.',[113,114,384,385],True)
 ],['Secure maintenance stand and helper','Length measuring equipment and appropriate spring-ring/locknut tools'])
